import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series_matrix*')):
    print('=====',f)
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'):break
        if any(k in l for k in ['title','characteristics','treatment','protocol','summary','design','source']):
            print(l[:1500].rstrip())

import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series_matrix*'))[1:]:
    print('=====',f)
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'):break
        if l.startswith('!Series') or any(k in l for k in ['title','characteristics','treatment','protocol','source']):
            parts=l.rstrip().split('\t')
            u=list(dict.fromkeys(parts[1:]))
            print(parts[0], ' | '.join(u)[:2500])

import pypdf,re
for i in [2,3]:
    t=' '.join(p.extract_text() or '' for p in pypdf.PdfReader(f'studies/papers/paper_{i}.pdf').pages)
    t=re.sub(r'\s+',' ',t)
    print('=====',i,len(t))
    for m in re.finditer(r'(hydroxy|OHT|OH-T|4-OH|OH-Tam|tamoxifen \()',t,re.I):
        print('..',t[max(0,m.start()-250):m.end()+250])
    for m in re.finditer(r'microarray|Affymetrix',t,re.I):
        print('MA..',t[max(0,m.start()-300):m.end()+300])
